+/* put the cells (r1, c1) and (r2, c2) in screen order */
+static void mcell_order(int *r1, int *c1, int *r2, int *c2)
+{
+	int t;
+	if (*r1 < *r2 || (*r1 == *r2 && *c1 <= *c2))
+		return;
+	t = *r1; *r1 = *r2; *r2 = t;
+	t = *c1; *c1 = *c2; *c2 = t;
