+
+/* write all of s[0..n) to the focused terminal */
+static void msend(char *s, int n)
+{
+	while (term->fd && n > 0) {
+		int w = write(term->fd, s, n);
+		if (w < 0 && errno == EINTR)
+			continue;
+		if (w <= 0)
+			return;
+		s += w;
+		n -= w;
+	}
