+/* an xterm SGR press and release of button at cell (r, c) */
+static void msendclick(int button, int r, int c)
+{
+	char buf[64];
+	int n = snprintf(buf, sizeof(buf), "\033[<%d;%d;%dM\033[<%d;%d;%dm",
+		button, c + 1, r + 1, button, c + 1, r + 1);
