+   close(), which only drops it with the last reference to the file */
+static void mouse_close(void)
+{
+	if (mfd < 0)
+		return;
+	ioctl(mfd, EVIOCGRAB, 0);
+	close(mfd);
+	mfd = -1;
+	mbprev = 0;
