+/* select the word under (r, c), or that cell alone if it is a blank */
+static void msel_word(int r, int c)
+{
+	int l = c, rt = c;
+	if (mword(term_getchar(r, c))) {
+		while (l > 0 && mword(term_getchar(r, l - 1)))
+			l--;
+		while (rt < pad_cols() - 1 && mword(term_getchar(r, rt + 1)))
+			rt++;
+	}
+	sel_br = sel_er = r;
+	sel_bc = l;
+	sel_ec = rt;
+	sel_on = 1;
