+		if (code == ABS_X || code == ABS_Y) {
+			int i = code == ABS_Y, w = (i ? fb_rows() : fb_cols()) - 1;
+			if (abs_max[i] > abs_min[i])
+				value = (int) ((long long) (value - abs_min[i]) * w /
+					(abs_max[i] - abs_min[i]));
+			if (i)
+				my = LIMIT(value, 0, w);
+			else
+				mx = LIMIT(value, 0, w);
+		}
+		break;
