+		press = value && !(mbprev & bit);
+		mbprev = value ? mbprev | bit : mbprev & ~bit;
+		if (bit == MB_LEFT) {
+			if (press && mmode)
+				msendclick(0, r, c);
+			else if (press)
+				mclick_ev(r, c);
+			dirty = selup = 1;
+		} else if (bit == MB_MIDDLE) {
+			if (press && mmode)
+				msendclick(2, r, c);
+			else if (press)
+				mpaste();
+			dirty = 1;
+		} else if (press) {
+			if (mmode) {
+				mmode = 0;	/* a right click leaves send mode */
+			} else if (sel_on || mark_on || mpend) {
+				mclear();	/* no repaint below: it hid the pointer */
+				return;
+			} else {
