+			(mdrag || r != mpress_r || c != mpress_c)) {
+		mdrag_to(r, c);
+		dirty = selup = 1;
+	}
+	if (dirty && (r != orow || c != ocol || dirty > 1))
+		mouse_refresh(selup);
+}
