+		lazy_flush();
+		return;
 	}
+	paint_screen();
+}
+
+/* the character a visible cell shows, history included */
+static int term_getchar(int r, int c)
+{
+	int hpos = term->hpos;
+	if (r < 0 || r >= pad_rows() || c < 0 || c >= pad_cols())
+		return ' ';
+	if (r < hpos)
+		return HISTROW(hpos - r)[c];
+	return term->screen[(r - hpos) * pad_cols() + c];
 }
 
